    rain(tex, area, n, E, o = {}) { const ang = o.ang ?? Math.PI / 2 + 0.25, v = o.v || 1500; for (let i = 0; i < N(n); i++) { const tx = area.x + R(-area.w * 0.6, area.w * 0.6), ty = area.y + R(-area.h * 0.7, area.h * 0.7), T = R(0.14, 0.2), sx = tx - Math.cos(ang) * v * T, sy = ty - Math.sin(ang) * v * T, dl = (o.delay || 0) + R(0, o.span ?? 0.5); p(tex, sx, sy, { vx: Math.cos(ang) * v, vy: Math.sin(ang) * v, drag: 1, rot: o.rot ?? ang, s: [o.s || 90, o.s || 90], asp: o.asp ?? 0.12, c: [E.hi, E.main], life: T, delay: dl, fout: 0.85, add: o.add }); if (o.hit !== false) at(dl + T, () => { ringThin(tx, ty + 8, E, 22, 0.34); if (Math.random() < 0.5) sparks(tx, ty, E, 3, 0.5); }); } },
