    sun(x, y, r, E, life = 1.0, o = {}) { add({ life, delay: o.delay, draw(k) { const al = k < 0.15 ? k / 0.15 : k > 0.8 ? (1 - k) / 0.2 : 1, yy = y + (o.fall || 0) * ease(k), rr = r * (o.grow ? 0.5 + 0.5 * ease(k) : 1) * (1 + 0.04 * Math.sin(k * 40)); G.spr('glow', x, yy, rr * 3.6, rr * 3.6, 0, rgb(E.main), 0.32 * al, true); for (let i = 0; i < 12; i++) { const a = k * 2 + i * TAU / 12, L = rr * (1.9 + 0.5 * Math.sin(k * 30 + i)); G.spr('ray', x + Math.cos(a) * (rr * 0.8 + L / 2), yy + Math.sin(a) * (rr * 0.8 + L / 2), L, L * 0.3, a, rgb(i % 2 ? E.hi : E.main), 0.7 * al, true); } if (o.dark) { G.spr('ring', x, yy, rr * 2.7, rr * 2.7, k * 3, rgb(E.hi), al, true); G.spr('core', x, yy, rr * 2.4, rr * 2.4, 0, rgb('#04010a'), 0.98 * al, false); } else { G.spr('core', x, yy, rr * 2.2, rr * 2.2, 0, rgb(E.main), al, true); G.spr('core', x, yy, rr * 1.5, rr * 1.5, 0, rgb(E.hi), al, true); } if (o.pos) { o.pos.x = x; o.pos.y = yy; } } }); },
    // 나무: 줄기가 솟고 가지가 뻗고 잎이 흩날린다 (세계수)
    tree(x, by, h, E, life = 1.1, delay = 0) { const TR = PALS.earth; add({ life, delay, draw(k) { const g = ease(Math.min(1, k / 0.35)), al = k > 0.75 ? (1 - k) / 0.25 : 1; G.seg(x, by, x, by - h * 0.7 * g, h * 0.16, h * 0.07, rgb(TR.lo), 0.95 * al, false); G.seg(x, by, x, by - h * 0.7 * g, h * 0.1, h * 0.04, rgb(TR.main), 0.6 * al, true); const cg = ease(Math.max(0, Math.min(1, (k - 0.2) / 0.35))), cy = by - h * 0.78; G.spr('glow', x, cy, h * 1.4 * cg, h * 1.0 * cg, 0, rgb(E.main), 0.45 * al, true); G.spr('crack', x, by - h * 0.62, h * 0.7 * cg, h * 0.5 * cg, 0, rgb(TR.lo), 0.85 * al, false); for (let i = 0; i < 11; i++) { const q = i * 2.39996, d = h * 0.34 * Math.sqrt(i / 11), bx = x + Math.cos(q) * d * 1.25, byy = cy + Math.sin(q) * d * 0.75, r = h * (0.42 - i * 0.012) * cg; G.spr('smoke', bx, byy + 6, r, r * 0.9, q, rgb(E.deep), 0.85 * al, false); G.spr('smoke', bx, byy, r * 0.92, r * 0.82, q + 1, rgb(i % 3 ? E.lo : E.main), 0.9 * al, false); G.spr('glow', bx - r * 0.12, byy - r * 0.16, r * 0.5, r * 0.5, 0, rgb(E.hi), 0.32 * al, true); } } }); K.drift('leaf', x, by - h * 0.75, 26, E.hi, E.main, { jx: h * 0.45, jy: h * 0.3, delay: delay + life * 0.3, span: life * 0.5, vy0: -40, vy1: 120 }); at(delay + life * 0.3, () => { shock(x, by, E, h * 0.5, 0.3); burst('glow', x, by - h * 0.7, 20, { v: [20, 120], sz: [5, 10, 2], c: [E.hi], life: [0.6, 1.2], jx: h * 0.4, jy: h * 0.3 }); }); },
    // 문: 두 문짝이 열리거나(open) 닫힌다
