    // 군단: 작은 그림들이 줄지어 지나간다
    army(tex, area, n, E, o = {}) { const dir = o.dir || 1; for (let i = 0; i < N(n); i++) { const y = area.y + R(-area.h * 0.6, area.h * 0.6), sx = area.x - dir * (area.w * 0.75 + R(0, 80)), T = R(0.45, 0.7), dl = (o.delay || 0) + R(0, o.span ?? 0.45), s = (o.s || 44) * R(0.8, 1.2); p(tex, sx, y, { vx: dir * area.w * 1.6 / T, drag: 1, s: [s, s], asp: o.asp || 1, rot: o.rot ?? 0, c: o.white ? ['#ffffff', E.hi] : [E.hi, E.main], life: T, delay: dl, fin: 0.15, fout: 0.75, add: o.add, wob: o.wob ?? 6, wf: 14 }); p('glow', sx, y, { vx: dir * area.w * 1.6 / T, drag: 1, s: [s * 1.8, s * 1.8], c: [E.main, E.lo], a: 0.35, life: T, delay: dl }); } },
    // 그물·격자
