  // ===== 탐색계 =====
  S('선제 일제사격', { aoe: (c) => { const { f, a, e, E } = c; p('ring', f.x, f.y, { s: [60, 20], c: [E.hi, E.main], life: 0.2 }); per(c, 0.02, (s) => { for (let j = -1; j <= 1; j++) fly({ from: { x: f.x + j * 14, y: f.y }, to: { x: s.x + j * 12, y: s.y + j * 6 }, speed: 1700, delay: (j + 1) * 0.04, el: e, hero: 'arrow', hs: 100, rw: 6, rlen: 12, gs: 36, sc: 0.7, hit: (x, y, ang) => { p(G.hero('arrow', e), x - Math.cos(ang) * 14, y - Math.sin(ang) * 14, { s: [100, 100], rot: ang, c: ['#ffffff'], add: false, life: 0.4, fout: 0.6 }); if (!j) F.accent(e, s.x, s.y, 0.85); } }); }); } });
  S('추적 화살', { hit: ({ f, t, e, E }) => { for (let i = 0; i < 4; i++) fly({ from: f, to: t, dur: 0.42, side: (i % 2 ? 1 : -1) * (90 + i * 30), delay: i * 0.08, ease: true, el: e, hero: 'arrow', hs: 100, rw: 7, rlen: 18, gs: 40, hit: (x, y, ang) => { cut(x, y, ang, 130, E, 0, 0.7); if (i === 3) hitAt({ el: e }, t.x, t.y, 1); else F.accent(e, x, y, 0.5); } }); p('ring', t.x, t.y, { s: [150, 50], c: ['#ff6a6a', '#ff3b3b'], life: 0.4 }); } });
  S('천리 사냥', { hit: ({ f, t, e, E }) => { FM.bird({ x: t.x - 200, y: t.y - 300, w: 50, h: 60 }, { x: t.x + 60, y: t.y - 60, w: 50, h: 60 }, { el: e }); add({ life: 0.5, delay: 0.2, draw(k) { const r = 190 - 130 * ease(k), col = rgb('#ff4a4a'); G.spr('ring', t.x, t.y, r, r, k * 5, col, 1, true); } }); at(0.72, () => { const sx = t.x - 60, sy = H() + 60, a = Math.atan2(t.y - sy, t.x - sx), ex = { x: t.x + Math.cos(a) * 300, y: t.y + Math.sin(a) * 300 }; fly({ from: { x: sx, y: sy }, to: ex, speed: 2600, el: e, hero: 'arrow', hs: 230, rw: 26, rlen: 20, gs: 140 }); K.line(sx, sy, ex.x, ex.y, E, 1.8, 0.02); at(dist({ x: sx, y: sy }, t) / 2600, () => { rays(t.x, t.y, E, 12, 200); thorns(t.x, by(t), E, 1.5, 0, 6, 100); hitAt({ el: e }, t.x, t.y, 1.3); }); }); } });
  S('사냥의 끝', { hit: ({ f, t, e }) => { FM.bite(f, t, { el: 'none' }); const a = dirOf(f, t); at(0.2, () => { K.line(f.x, f.y, t.x + Math.cos(a) * 220, t.y + Math.sin(a) * 220, DK, 1.6); cut(t.x, t.y, a, 320, DK, 0.03, 1.2); hitAt({ el: 'dark' }, t.x, t.y, 1.1); }); } });
  S('연속 습격', { hit: ({ f, t, e }) => { for (let i = 0; i < 6; i++) { const q = (i % 2 ? 0.5 : -0.5) + Math.PI * (i % 2), d = 170; at(i * 0.07, () => { K.line(t.x - Math.cos(q) * d, t.y - Math.sin(q) * d + (i - 3) * 8, t.x + Math.cos(q) * d, t.y + Math.sin(q) * d + (i - 3) * 8, DK, 0.9, 0, 0.2); cut(t.x, t.y + (i - 3) * 8, q, 150, DK, 0.03, 0.8); }); } at(0.48, () => hitAt({ el: 'dark' }, t.x, t.y, 1)); } });
  S('사냥감의 숨', { hit: ({ f, t, e }) => { const Rd = P('red'); for (let i = 0; i < 2; i++) { shock(t.x, t.y, Rd, 60, 1, i * 0.32, 0.25); ringThin(t.x, t.y, Rd, 90, 1, 0.06 + i * 0.32, 0.25); } at(0.78, () => { const a = dirOf(f, t); K.wash(Rd, 0.3, 0.12); K.line(t.x - Math.cos(a) * 280, t.y - Math.sin(a) * 280, t.x + Math.cos(a) * 280, t.y + Math.sin(a) * 280, Rd, 1.2); burst('drop', t.x, t.y, 20, { ang: a, spread: 0.6, v: [240, 640], sz: [12, 22, 5], asp: 0.5, face: true, c: [BL.hi, BL.main], add: false, life: [0.4, 0.8], ay: 700 }); hitAt({ el: 'dark', big: true }, t.x, t.y, 1.2); }); } });
  S('파동 붕괴', { aoe: (c) => { const { f, a, e, E } = c; for (let i = 0; i < 4; i++) shock(f.x, f.y, CY, 220 + i * 120, 1, i * 0.1, 0.7); per(c, 0.06, (s) => at(0.35, () => { for (let i = 0; i < 3; i++) p('wave', s.x, s.y, { s: [150 - i * 30, 20], c: [CY.hi, CY.main], life: 0.3, delay: i * 0.04, fin: 0.3, fout: 0.8 }); at(0.25, () => { burst('shard', s.x, s.y, 12, { v: [220, 560], sz: [16, 30, 5], asp: 0.45, c: [CY.hi, CY.main], life: [0.3, 0.6], rrot: true, rvr: 12 }); F.accent(e, s.x, s.y, 0.9); }); })); } });
  S('박동 감지', { sup: ({ t, e }) => { add({ life: 0.9, draw(k) { const al = k > 0.7 ? (1 - k) / 0.3 : 1, n = 24, w = 150, head = k * 1.6; for (let i = 0; i < n; i++) { const u0 = i / n, u1 = (i + 1) / n; if (u1 > head) break; const f1 = (u) => (Math.abs(u - 0.5) < 0.08 ? Math.sin((u - 0.42) / 0.16 * TAU) * 34 : 0); G.seg(t.x - w / 2 + u0 * w, t.y - f1(u0), t.x - w / 2 + u1 * w, t.y - f1(u1), 5, 5, rgb(CY.hi), al, true); G.seg(t.x - w / 2 + u0 * w, t.y - f1(u0), t.x - w / 2 + u1 * w, t.y - f1(u1), 16, 16, rgb(CY.main), 0.4 * al, true); } } }); for (let i = 0; i < 2; i++) ringThin(t.x, t.y, CY, 70, 1, i * 0.3, 0.3); at(0.25, () => SP.buff(t, 'bolt', { all: true })); } });
