  S('천리 일격', { hit: ({ f, t, e, E }) => { const a = dirOf(f, t); p('eye', f.x, f.y - f.h * 0.6, { s: [20, 100], asp: 0.6, c: [E.hi, E.main], life: 0.5, pop: true }); at(0.25, () => { K.line(f.x - Math.cos(a) * 200, f.y - Math.sin(a) * 200, t.x + Math.cos(a) * 300, t.y + Math.sin(a) * 300, E, 1.8); for (let i = 0; i < 5; i++) p('ring', f.x + (t.x - f.x) * (i + 1) / 5, f.y + (t.y - f.y) * (i + 1) / 5, { rot: a, s: [20, 90], asp: 1, c: [E.hi, E.main], life: 0.3, pop: true, delay: i * 0.02 }); hitAt({ el: e }, t.x, t.y, 1.1); }); } });
  S('미래 시야', { sup: ({ t, e }) => { K.big('eye', t.x, t.y - t.h * 1.1, 110, GD, { asp: 0.55, life: 1.0 }); for (let i = 0; i < 3; i++) add({ life: 0.6, delay: 0.15 + i * 0.15, draw(k) { G.spr('ring', t.x, t.y - 60 + 110 * k, 110, 34, 0, rgb(GD.hi), 1 - k, true); } }); at(0.3, () => SP.buff(t, 'holy', { all: true })); } });
  S('전지의 눈', { hit: ({ f, t, e }) => { const eye = { x: W() / 2, y: Math.max(90, t.y - 300) }, a = dirOf(eye, t); K.big('eye', eye.x, eye.y, 400, GD, { asp: 0.55, life: 1.3 }); add({ life: 1.2, draw(k) { const al = k > 0.75 ? (1 - k) / 0.25 : Math.min(1, k * 4); for (let i = 0; i < 16; i++) { const q = i * TAU / 16 + k, L = 240; G.spr('ray', eye.x + Math.cos(q) * (90 + L / 2), eye.y + Math.sin(q) * (60 + L / 3), L, 40, q, rgb(GD.hi), 0.5 * al, true); } } }); at(0.6, () => { G.beam(eye.x, eye.y, t.x + Math.cos(a) * 240, t.y + Math.sin(a) * 240, GD, { w: 20, life: 0.5 }); K.wash(GD, 0.3, 0.16); F.accent('holy', t.x, t.y, 1.5); hitAt({ el: e }, t.x, t.y, 1.3); }); } });
  const WA = el('water');
  S('미궁의 덫', { hit: ({ f, t, e }) => { add({ life: 0.9, draw(k) { const g = Math.min(1, k / 0.5), al = k > 0.75 ? (1 - k) / 0.25 : 1; let x = t.x - 80, y = t.y - 80, dx = 1, dy = 0, len = 160, drawn = 0, total = 0; const segs = []; for (let i = 0; i < 9; i++) { segs.push([x, y, x + dx * len, y + dy * len, len]); total += len; x += dx * len; y += dy * len; [dx, dy] = [-dy, dx]; if (i % 2) len -= 34; } const lim = total * g; for (const [x1, y1, x2, y2, L] of segs) { if (drawn >= lim) break; const u = Math.min(1, (lim - drawn) / L); G.seg(x1, y1, x1 + (x2 - x1) * u, y1 + (y2 - y1) * u, 6, 6, rgb(WA.hi), al, true); G.seg(x1, y1, x1 + (x2 - x1) * u, y1 + (y2 - y1) * u, 16, 16, rgb(WA.main), 0.4 * al, true); drawn += L; } } }); at(0.5, () => { F.accent('water', t.x, t.y, 1.2); F.stars(t); hitAt({ el: 'water' }, t.x, t.y, 1); }); } });
  S('귀환의 물길', { sup: ({ t, e }) => { for (let i = 0; i < N(26); i++) p('drop', t.x + R(-16, 16), t.y + 260, { rot: -Math.PI / 2, vy: R(-640, -420), vx: R(-20, 20), drag: 1, s: [R(16, 26), 8], asp: 0.5, c: [WA.hi, WA.main], life: 0.5, delay: R(0, 0.5), wob: 10 }); K.pillar(t.x, by(t), WA, 30, 0.9, 0.1, { up: true, h: 300, a: 0.6 }); at(0.4, () => SP.revive(t, 'water')); } });
  S('미궁 붕락', { aoe: (c) => { const { f, a, s, e } = c; K.net(a, P('steel'), 0.7, 0, 6); at(0.45, () => { smoke(a.x, a.y, 14, 1.6, ['#5c6272', '#16181f'], { a: 0.55, jx: a.w * 0.5, jy: 70 }); burst('shard', a.x, a.y - 80, 26, { ang: Math.PI / 2, spread: 0.5, v: [200, 700], sz: [22, 44, 10], asp: 0.5, c: ['#b9c4d6', '#5f6c84'], add: false, life: [0.4, 0.8], ay: 1400, rrot: true, rvr: 8, jx: a.w * 0.6 }); AO.orb(f, a, s, { el: 'water' }); }); } });

